"""Generate an interactive, self-contained graph.html-style brain viewer."""
from __future__ import annotations
import json, math

COLORS=["#4E79A7","#F28E2B","#E15759","#76B7B2","#59A14F","#EDC948","#B07AA1","#FF9DA7","#9C755F","#BAB0AC"]

def _payload(cg,max_nodes=2500):
    d=cg.to_dict() if hasattr(cg,"to_dict") else cg
    src=sorted(d.get("nodes",[]),key=lambda n:(-n.get("degree",0),-n.get("rank",0)))[:max_nodes]
    ids={n.get("id") for n in src}; nodes=[]
    for i,item in enumerate(src):
        n=dict(item); a=i*2.3999632297; r=24+18*math.sqrt(i+1)
        n.update(x=math.cos(a)*r,y=math.sin(a)*r)
        n.setdefault("name",n.get("label",n.get("id","?"))); n.setdefault("kind",n.get("file_type","unknown"))
        n.setdefault("file",n.get("source_file","")); n.setdefault("degree",0); n.setdefault("community",0)
        nodes.append(n)
    edges=[e for e in d.get("edges",[]) if e.get("source") in ids and e.get("target") in ids]
    counts={}
    for n in nodes: counts[n["community"]]=counts.get(n["community"],0)+1
    legend=[{"id":k,"label":f"Community {k}","count":v,"color":COLORS[k%len(COLORS)]} for k,v in sorted(counts.items(),key=lambda x:-x[1])]
    return {"meta":d.get("meta",{}),"nodes":nodes,"edges":edges,"legend":legend,"colors":COLORS}

