def write_brain(cg,path,max_nodes=2500):
    d=_payload(cg,max_nodes)
    with open(path,"w",encoding="utf-8") as f:f.write(HTML.replace("__DATA__",json.dumps(d,separators=(",",":"),ensure_ascii=False)))
    return d.get("meta",{})

def json_to_html(json_path,html_path,max_nodes=2500):
    from .graph import CodeGraph
    return write_brain(CodeGraph.load(json_path),html_path,max_nodes)
